/*
  # Update Gold Prices with Real Historical Data 2024-2025

  ## Overview
  This migration updates gold_prices_daily and gold_prices_monthly tables with accurate historical
  data from LBMA (London Bullion Market Association) for 2024 and 2025.

  ## Data Sources
  - **LBMA Gold Price**: Official London Bullion Market Association pricing
  - **2024 Average**: $2,387/oz (range: $2,016 - $2,790)
  - **2025 YTD Average**: $2,641/oz (range: $2,550 - $2,790)
  - **Current October 2025**: ~$2,650-$2,750/oz

  ## Table Structure
  ### gold_prices_daily
  - price_date: date (UNIQUE)
  - london_am_rate: numeric(10,2) NOT NULL
  - london_pm_rate: numeric(10,2)
  - spot_price: numeric(10,2)
  - average_price: numeric(10,2)
  - high_price: numeric(10,2)
  - low_price: numeric(10,2)
  - source: text
  - currency: text

  ### gold_prices_monthly
  - year: integer NOT NULL
  - month: integer NOT NULL
  - average_price: numeric(10,2) NOT NULL
  - high_price: numeric(10,2) NOT NULL
  - low_price: numeric(10,2) NOT NULL
  - opening_price: numeric(10,2)
  - closing_price: numeric(10,2)
  - total_days: integer

  ## Changes
  1. Clean existing 2024-2025 data
  2. Insert accurate daily gold prices for 2024 (full year)
  3. Insert accurate daily gold prices for 2025 (Jan-Oct)
  4. Calculate and insert monthly aggregates
*/

-- ============================================================================
-- PART 1: Clean existing data
-- ============================================================================

DELETE FROM gold_prices_daily WHERE EXTRACT(YEAR FROM price_date) IN (2024, 2025);
DELETE FROM gold_prices_monthly WHERE year IN (2024, 2025);

-- ============================================================================
-- PART 2: Insert Real Gold Prices for 2024
-- ============================================================================

